import numpy as np

def _tip(lengths, q):
    a = np.cumsum(q)
    return np.array([np.sum(np.asarray(lengths) * np.cos(a)), np.sum(np.asarray(lengths) * np.sin(a))])

def _fd(lengths, q, h=1e-6):
    q = np.asarray(q, dtype=float)
    return np.column_stack([(_tip(lengths, q + h * e) - _tip(lengths, q - h * e)) / (2 * h) for e in np.eye(len(q))])

