assert np.allclose(J, [[-0.65, -0.4], [0.5 * np.cos(np.pi / 6), 0.0]], atol=1e-12), J
rng = np.random.default_rng(7)
for n in (1, 2, 3, 5):
    lengths = rng.uniform(0.1, 0.6, n)
    for _ in range(5):
        q = rng.uniform(-np.pi, np.pi, n)
        assert np.allclose(planar_jacobian(lengths, q), _fd(lengths, q), atol=1e-7), (n, q)
assert abs(np.linalg.det(planar_jacobian([0.5, 0.4], [0.3, 0.0]))) < 1e-12, "a straight 2R arm is singular"

